replace('<p id="routeCount" class="small"></p>', '<div class="partner-export-actions"><button id="exportPartners">Export filtered partners (Excel)</button><span>Profiles, routes, projects and source evidence</span></div><p id="partnerExportStatus" class="export-status" role="status" aria-live="polite"></p><p id="routeCount" class="small"></p>')
